# Get all player appearances with their tournament info
winner_tours = df[['winner_id', 'winner_name', 'winner_ioc', 'tourney_id']].rename(
    columns={'winner_id': 'player_id', 'winner_name': 'player_name', 'winner_ioc': 'player_ioc'}
)

loser_tours = df[['loser_id', 'loser_name', 'loser_ioc', 'tourney_id']].rename(
    columns={'loser_id': 'player_id', 'loser_name': 'player_name', 'loser_ioc': 'player_ioc'}
)

# Combine all appearances
all_tours = pd.concat([winner_tours, loser_tours])

# Count unique tournaments per player
tour_counts = all_tours.groupby(['player_id', 'player_name', 'player_ioc'])['tourney_id'].nunique().reset_index()
tour_counts.columns = ['player_id', 'player_name', 'player_ioc', 'num_tournaments']

# Get the player with the most tournaments
top_player = tour_counts.sort_values('num_tournaments', ascending=False).iloc[0]

# Extract first name
first_name = top_player['player_name'].split()[0]

result = pd.DataFrame({
    'first_name': [first_name],
    'country_code': [top_player['player_ioc']]
})

# Count unique tournaments per player (combining winner and loser appearances)
all_player_tours = pd.concat([
    df[['winner_id', 'winner_name', 'winner_ioc', 'tourney_id']].rename(columns={
        'winner_id': 'player_id', 
        'winner_name': 'player_name', 
        'winner_ioc': 'player_ioc'
    }),
    df[['loser_id', 'loser_name', 'loser_ioc', 'tourney_id']].rename(columns={
        'loser_id': 'player_id', 
        'loser_name': 'player_name', 
        'loser_ioc': 'player_ioc'
    })
])

player_tour_counts = all_player_tours.groupby(['player_id', 'player_name', 'player_ioc'])['tourney_id'].nunique().reset_index()
player_tour_counts.columns = ['player_id', 'player_name', 'player_ioc', 'tour_count']
player_tour_counts = player_tour_counts.sort_values('tour_count', ascending=False)

top_player = player_tour_counts.iloc[0]
first_name = top_player['player_name'].split()[0]
country_code = top_player['player_ioc']

result = pd.DataFrame({
    'first_name': [first_name],
    'country_code': [country_code]
})
